from collections import namedtuple, Mapping

from enum import Enum

cell_search_template_4G = ("""forw mte SetMueRadioContextCell {radio_context_Id} {cell_Id} """
                           """{downlink_carrier_frequency} {system_bandwidth} [{number_of_eNB_transmit_antennas}] """
                           """[{subframe_assignment}{special_subframe_patterns}] [{number_of_receive_antennas}]""")

cell_search_template_5G = (
    """forw mte NrSetMueRadioContextCell {radio_context_Id} {cell_Id} {downlink_carrier_frequency} """
    """{system_bandwidth} [{uplink_carrier_frequency}] """
    """[{uplink_bandwidth}] [{number_of_receive_antennas}] """
    """[{absoluteFrequencyPointA}{absoluteFrequencySSB}] [{gnb_downlink_carrier_frequency}] """
    """[{ssb_subcarrier_spacing}] [{frequencyShift7p5khz}]""")


class SystemBandwidth(Enum):
    one = 1
    three = 3
    five = 5
    ten = 10
    fifteen = 15
    twenty = 20

    def __str__(self):
        return str(self.value)


class FrequencyShift7p5khz(Enum):
    supported = 1
    not_supported = 0
    default = ""

    def __str__(self):
        return str(self.value)


class SubFrames(Enum):
    zero = 0
    one = 1
    two = 2
    three = 3
    four = 4
    five = 5
    six = 6
    seven = 7
    eight = 8
    nine = 9
    empty = ""

    def __str__(self):
        return str(self.value)


class ReceiveAntennas(Enum):
    zero = 0
    one = 1
    two = 2
    four = 4
    eight = 8

    def __str__(self):
        return str(self.value)


class Bandwidth(Enum):
    five = 5
    ten = 10
    fifteen = 15
    twenty = 20
    twentyfive = 25
    thirty = 30
    forty = 40
    fifty = 50
    sixty = 60
    seventy = 70
    eighty = 80
    ninety = 90
    hundred = 100

    def __str__(self):
        return str(self.value)


def namedtuple_with_defaults(typename, field_names, default_values=()):
    T = namedtuple(typename, field_names)
    T.__new__.__defaults__ = (None,) * len(T._fields)
    if isinstance(default_values, Mapping):
        prototype = T(**default_values)
    else:
        prototype = T(*default_values)
    T.__new__.__defaults__ = tuple(prototype)
    return T


CellSearchParams4G = namedtuple_with_defaults('CellSearchParams4G',
                                              ['radio_context_Id', 'cell_Id', 'downlink_carrier_frequency',
                                               'number_of_enb_transmit_antennas',
                                               'sub_frame_assignment',
                                               'special_subframe_patterns',
                                               'system_bandwidth',
                                               'number_of_receive_antennas'],
                                              {'number_of_enb_transmit_antennas': ReceiveAntennas.one,
                                               'sub_frame_assignment': SubFrames.empty,
                                               'special_subframe_patterns': SubFrames.empty,
                                               'system_bandwidth': SystemBandwidth.five,
                                               'number_of_receive_antennas': None})

CellSearchParams5G = namedtuple_with_defaults('CellSearchParams5G',
                                              ['radio_context_Id', 'cell_Id', 'downlink_carrier_frequency',
                                               'system_bandwidth',
                                               'gnb_downlink_carrier_frequency', 'ssb_subcarrier_spacing',
                                               'uplink_bandwidth',
                                               'absolute_frequency_pointA',
                                               'absolute_frequency_SSB',
                                               'uplink_carrier_frequency',
                                               'number_of_receive_antennas',
                                               'frequencyShift7p5khz'],
                                              {'uplink_bandwidth': "",
                                               'absolute_frequency_pointA': "", 'absolute_frequency_SSB': "",
                                               'uplink_carrier_frequency': "",
                                               'number_of_receive_antennas': ReceiveAntennas.two,
                                               'frequencyShift7p5khz': FrequencyShift7p5khz.default})


class CellSearch(object):
    def __add__(self, other):
        return str(self) + "\n" + str(other)

    def __radd__(self, other):
        return str(other) + "\n" + str(self)


class CellSearch5G(CellSearch, CellSearchParams5G):
    """
        Generates command to set the cell information for a radio context(5G)
    """

    def __str__(self):
        return cell_search_template_5G.format(radio_context_Id=self.radio_context_Id,
                                              cell_Id=self.cell_Id,
                                              downlink_carrier_frequency=self.downlink_carrier_frequency,
                                              system_bandwidth=Bandwidth(self.system_bandwidth),
                                              uplink_carrier_frequency=self.uplink_carrier_frequency,
                                              uplink_bandwidth=self.get_uplink_bandwidth(),
                                              number_of_receive_antennas=ReceiveAntennas(
                                                  self.number_of_receive_antennas),
                                              absoluteFrequencyPointA=self.get_frequency_pointA(),
                                              absoluteFrequencySSB=self.absolute_frequency_SSB,
                                              gnb_downlink_carrier_frequency=self.gnb_downlink_carrier_frequency,
                                              ssb_subcarrier_spacing=self.ssb_subcarrier_spacing,
                                              frequencyShift7p5khz=FrequencyShift7p5khz(self.frequencyShift7p5khz))

    def get_uplink_bandwidth(self):
        return str(Bandwidth(
            self.uplink_bandwidth)) if self.uplink_bandwidth != "" else str(Bandwidth(self.system_bandwidth))

    def get_frequency_pointA(self):
        return self.absolute_frequency_pointA if self.absolute_frequency_pointA == "" else str(
            self.absolute_frequency_pointA) + " "


class CellSearch4G(CellSearch, CellSearchParams4G):
    """
           Generates command to set the cell information for a radio context(4G)
    """

    def __str__(self):

        return cell_search_template_4G.format(radio_context_Id=self.radio_context_Id,
                                              cell_Id=self.cell_Id,
                                              downlink_carrier_frequency=self.downlink_carrier_frequency,
                                              system_bandwidth=self.system_bandwidth,
                                              number_of_eNB_transmit_antennas=self.number_of_enb_transmit_antennas,
                                              subframe_assignment=self.__get_subframe_assignment(),
                                              special_subframe_patterns=SubFrames(self.special_subframe_patterns),
                                              number_of_receive_antennas=self.__get_number_of_receive_antennas())

    def __get_subframe_assignment(self):
        return "" if self.sub_frame_assignment == SubFrames.empty else \
            str(SubFrames(self.sub_frame_assignment)) + " "

    def __get_number_of_receive_antennas(self):
        if self.number_of_receive_antennas is not None:
            return self.number_of_receive_antennas
        elif ReceiveAntennas(self.number_of_enb_transmit_antennas) == ReceiveAntennas.zero or \
                ReceiveAntennas(self.number_of_enb_transmit_antennas) == ReceiveAntennas.one:
            return ReceiveAntennas.one
        else:
            return ReceiveAntennas.two
